// web.dev pattern: scheduler.yield if available, otherwise setTimeout
function yieldToMain() {
  if (globalThis.scheduler?.yield) {
    return scheduler.yield();
  }
  return new Promise(resolve => {
    setTimeout(resolve, 0);
  });
}

async function processAll(items) {
  let last = performance.now();
  for (const item of items) {
    work(item);
    if (performance.now() - last > 10) { // yield roughly every 10 ms of work
      await yieldToMain();
      last = performance.now();
    }
  }
}

let buffer = '';
let scheduled = false;

function onChunk(text) {          // called for every chunk from the stream
  buffer += text;
  if (!scheduled) {
    scheduled = true;
    requestAnimationFrame(flush); // at most one flush per frame
  }
}

function flush() {
  scheduled = false;
  appendToMessage(buffer);        // one state update per frame
  buffer = '';
}

const doneHtml = []; // HTML of finished blocks, never parsed again
let done = 0;

function render(source) {
  const lastBreak = source.lastIndexOf('\n\n');
  if (lastBreak > done) {
    doneHtml.push(parse(source.slice(done, lastBreak)));
    done = lastBreak;
  }
  // only the last, still-open block is re-parsed
  return doneHtml.join('') + parse(source.slice(done));
}
